/// Mesh vertex, matching C `ShapeVertex` (src/renderer/shapes.h).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ShapeVertex {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

/// Polygon face, matching C `ShapeFace` (src/renderer/shapes.h).
/// `num_verts == 2` is a Face2 wireframe line segment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ShapeFace {
    pub vertex_indices: [u16; 12],
    pub num_verts: u8,
    pub color_index: u8,
    /// Authored face normal in the shared GL-up coordinate model.
    pub normal: [i16; 3],
    /// Source `vizis` triangle; `None` means deliberately two-sided.
    pub visibility_vertices: Option<[u16; 3]>,
}

/// One compiled shape, matching C `ShapeDataEntry` (shape_data.h).
#[derive(Debug, Clone, Copy)]
pub struct ShapeDataEntry {
    pub shape_id: u16,
    pub vertices: &'static [ShapeVertex],
    pub animation_frames: &'static [&'static [ShapeVertex]],
    pub faces: &'static [ShapeFace],
    pub default_color_table: &'static str,
    pub name: &'static str,
}

const fn v(x: f32, y: f32, z: f32) -> ShapeVertex {
    ShapeVertex { x, y, z }
}

const fn f(
    vertex_indices: [u16; 12],
    num_verts: u8,
    color_index: u8,
    normal: [i16; 3],
    visibility_vertices: Option<[u16; 3]>,
) -> ShapeFace {
    ShapeFace {
        vertex_indices,
        num_verts,
        color_index,
        normal,
        visibility_vertices,
    }
}

